class Solution {
  public int catchMaximumAmountofPeople(int[] team, int dist) {
    // greedy: each "it" catches the leftmost catchable runner still free
    int n = team.length, caught = 0;
    for (int it = 0, runner = 0; it < n; it++) {
      if (team[it] != 1) continue;
      runner = Math.max(runner, it - dist);
      while (runner < n && runner <= it + dist && team[runner] != 0) runner++;
      if (runner < n && runner <= it + dist) {
        caught++;
        runner++;
      }
    }
    return caught;
  }
}
